// `setup-host.ps1`: the one-time host preparation and broker install (ticket 21), generated by
// `arashouse setup` from the same constants as the guards (names.ts, guards.ts, flavors.ts) and run by
// the captain in an elevated Windows PowerShell. Pure: this module only builds text and checks what
// the script recorded. docs/setup.md describes the script; its tests are setup-host.test.ts (the text)
// and test/setup-host.test.ts (the script under Windows PowerShell, when there is one).

import { createHash } from "node:crypto";
import { FLAVORS, FLAVOR_KEYS, type FlavorKey, type HostPrerequisite } from "./flavors.js";
import { assertValidRoot } from "./guards.js";
import {
  BROKER_SERVICE_NAME,
  DEFAULT_INSTALL_ROOT,
  brokerAppDir,
  brokerClientScript,
  brokerDir,
  brokerEntryScript,
  brokerServiceExe,
  brokerServiceLog,
  setupRecordFile,
} from "./names.js";
import { win32 } from "node:path";

/** The folders `setup` creates under the install root, in this order. */
export const ROOT_FOLDERS = ["golden", "slots", "vaults", "sqldata", "staging", "logs", "secrets", "golden-build", "broker"] as const;
export type RootFolder = (typeof ROOT_FOLDERS)[number];

/** Who a folder's ACL names. `sql` is the SQL Server service account, read from the service definition. */
export type AclPrincipal = "system" | "administrators" | "broker" | "worker" | "sql";
export type AclRight = "full" | "modify" | "read";

const ADMINS: Readonly<Partial<Record<AclPrincipal, AclRight>>> = { system: "full", administrators: "full", broker: "modify" };

/**
 * Each folder's whole DACL: not inherited from the root, applied to the folder, its subfolders and
 * files. The worker may change `staging\` only, read `slots\` (to take code out, ticket 43) and
 * `broker\` (the client and its token, docs/broker.md), and nothing else; `secrets\` is SYSTEM's and
 * the broker's alone. The SQL Server account reads backups in `golden\` and `staging\` and owns the
 * files in `sqldata\`.
 */
export const FOLDER_ACL: Readonly<Record<RootFolder, Readonly<Partial<Record<AclPrincipal, AclRight>>>>> = {
  golden: { ...ADMINS, sql: "read" },
  slots: { ...ADMINS, worker: "read" },
  vaults: ADMINS,
  sqldata: { ...ADMINS, sql: "modify" },
  staging: { ...ADMINS, worker: "modify", sql: "read" },
  logs: ADMINS,
  secrets: { system: "full", broker: "modify" },
  "golden-build": ADMINS,
  broker: { ...ADMINS, worker: "read" },
};

/** The SQL Server instance whose service account the ACLs name (the host's default instance). */
export const SQL_SERVICE_NAME = "MSSQLSERVER";

/** The Node major the broker needs on Windows (package.json `engines`). */
export const MIN_NODE_MAJOR = 20;

/** `NT SERVICE\<name>`: the service's virtual account. */
export function serviceAccount(service: string = BROKER_SERVICE_NAME): string {
  return `NT SERVICE\\${service}`;
}

/** The SID Windows gives `NT SERVICE\<name>`: S-1-5-80 and the SHA-1 of the upper-case name in UTF-16LE, as five words. */
export function serviceSid(service: string = BROKER_SERVICE_NAME): string {
  const hash = createHash("sha1").update(Buffer.from(service.toUpperCase(), "utf16le")).digest();
  return `S-1-5-80-${[0, 4, 8, 12, 16].map((i) => hash.readUInt32LE(i)).join("-")}`;
}

// ---- prerequisites ---------------------------------------------------------------------------------

/** The IIS role services (`HKLM\SOFTWARE\Microsoft\InetStp\Components`) the Aras applications use. */
export const IIS_COMPONENTS = [
  "W3SVC",
  "StaticContent",
  "DefaultDocument",
  "HttpErrors",
  "RequestFiltering",
  "ASPNET45",
  "NetFxExtensibility45",
  "ISAPIExtensions",
  "ISAPIFilter",
] as const;

/** .NET Framework 4.7.2's `Release` value. */
const NETFX_472_RELEASE = 461808;

/**
 * A PowerShell expression per prerequisite that is `$null` when it is present and otherwise says what
 * is missing. Each one only reads (the registry, or a folder under `$env:ProgramFiles`).
 */
const PREREQUISITE_CHECKS: Readonly<Record<HostPrerequisite, string>> = {
  iis: "Test-Iis",
  "netfx-4.7.2": `Test-NetFx ${NETFX_472_RELEASE}`,
  "aspnetcore-2.1": "Test-AspNetCore '2.1'",
  "aspnetcore-6.0": "Test-AspNetCore '6.0'",
  "aspnetcore-8.0": "Test-AspNetCore '8.0'",
  "ancm-v1": "Test-RegistryKey 'HKLM:\\SOFTWARE\\Microsoft\\IIS Extensions\\IIS AspNetCore Module' 'the ASP.NET Core Module (V1) for IIS'",
  "ancm-v2": "Test-RegistryKey 'HKLM:\\SOFTWARE\\Microsoft\\IIS Extensions\\IIS AspNetCore Module V2' 'the ASP.NET Core Module V2 for IIS'",
  "vcredist-14-x64": "Test-VcRedist",
};

/** The prerequisites of `flavors`, each with the flavors that need it, in registry order. */
export function prerequisitesFor(flavors: readonly FlavorKey[]): { id: HostPrerequisite; flavors: FlavorKey[] }[] {
  const out = new Map<HostPrerequisite, FlavorKey[]>();
  for (const key of FLAVOR_KEYS) {
    if (!flavors.includes(key)) continue;
    for (const id of FLAVORS[key].hostPrerequisites) out.set(id, [...(out.get(id) ?? []), key]);
  }
  return [...out].map(([id, keys]) => ({ id, flavors: keys }));
}

// ---- the generated script ----------------------------------------------------------------------

/** One file of the broker build the script installs, and its SHA-256, so the script installs exactly what was reviewed. */
export interface AppFile {
  /** Relative to `<root>\broker\app`, with backslashes. */
  readonly path: string;
  readonly sha256: string;
}

export interface WorkerIdentity {
  /** `DOMAIN\user`, as `whoami` prints it. */
  readonly name: string;
  readonly sid: string;
}

export interface SetupScriptOptions {
  /** The install root; `DEFAULT_INSTALL_ROOT` unless a test names another. Vetted by `assertValidRoot`. */
  readonly root?: string;
  /** The arashouse version that generated the script and whose build it installs. */
  readonly version: string;
  /** The Windows user the workers run as (WSL interop runs as this user). */
  readonly worker: WorkerIdentity;
  /** The flavors whose prerequisites are checked: those with media in `media/`. */
  readonly flavors: readonly FlavorKey[];
  /** The broker build (`dist\`), as copied next to the script under `app\`. */
  readonly appFiles: readonly AppFile[];
  /** The SHA-256 of the `package.json` copied next to the script. */
  readonly packageJsonSha256: string;
}

const WORKER_NAME = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}\\[A-Za-z0-9][A-Za-z0-9._ $-]{0,63}$/;
const USER_SID = /^S-1-5-21(-\d{1,10}){4}$/;
const APP_PATH = /^[A-Za-z0-9_.-]+(\\[A-Za-z0-9_.-]+)*$/;
const SHA256 = /^[0-9a-f]{64}$/;
const VERSION = /^[0-9A-Za-z.+-]{1,64}$/;

/** A PowerShell single-quoted string. */
export function psQuote(text: string): string {
  return `'${text.replace(/'/g, "''")}'`;
}

/** A C# verbatim string. */
function csQuote(text: string): string {
  return `@"${text.replace(/"/g, '""')}"`;
}

function checkOptions(options: SetupScriptOptions): void {
  if (!VERSION.test(options.version)) throw new Error("the version must be 1 to 64 letters, digits, '.', '+' or '-'");
  if (!WORKER_NAME.test(options.worker.name)) throw new Error(`the worker user must be DOMAIN\\user, got "${options.worker.name}"`);
  if (!USER_SID.test(options.worker.sid)) throw new Error("the worker user's SID must be an account SID (S-1-5-21-...)");
  if (options.flavors.length === 0) throw new Error("at least one flavor's prerequisites must be checked");
  if (options.appFiles.length === 0) throw new Error("the broker build is empty");
  const seen = new Set<string>();
  for (const f of options.appFiles) {
    if (!APP_PATH.test(f.path) || f.path.split("\\").some((s) => s === "." || s === "..")) throw new Error(`unusable broker build path "${f.path}"`);
    if (!SHA256.test(f.sha256)) throw new Error(`the SHA-256 of ${f.path} is not 64 hex digits`);
    if (seen.has(f.path.toLowerCase())) throw new Error(`the broker build lists ${f.path} twice`);
    seen.add(f.path.toLowerCase());
  }
  if (!seen.has("broker\\index.js") || !seen.has("broker\\client.js")) throw new Error("the broker build has no broker\\index.js or broker\\client.js");
  if (!SHA256.test(options.packageJsonSha256)) throw new Error("the SHA-256 of package.json is not 64 hex digits");
}

/** The service wrapper's C# source. `@@NODE@@` is replaced by the script with the node.exe it found. */
export function brokerWrapperSource(root: string = DEFAULT_INSTALL_ROOT): string {
  return `using System;
using System.Diagnostics;
using System.IO;
using System.ServiceProcess;
using System.Text;

// The ${BROKER_SERVICE_NAME} service, compiled by setup-host.ps1 (arashouse, ticket 21): it runs the broker
// under Node and stops it with the service. When Node exits on its own, this process exits with code 1,
// so the service's recovery options start it again.
public sealed class ArasHouseBrokerService : ServiceBase
{
    const string NodeExe = @"@@NODE@@";
    const string EntryScript = ${csQuote(brokerEntryScript(root))};
    const string WorkDir = ${csQuote(brokerDir(root))};
    const string LogFile = ${csQuote(brokerServiceLog(root))};
    static readonly object LogLock = new object();
    Process child;
    volatile bool stopping;

    public ArasHouseBrokerService()
    {
        ServiceName = "${BROKER_SERVICE_NAME}";
        CanStop = true;
        CanShutdown = true;
    }

    static void Log(string line)
    {
        if (line == null) return;
        lock (LogLock)
        {
            try { File.AppendAllText(LogFile, DateTime.UtcNow.ToString("o") + " " + line + Environment.NewLine, Encoding.UTF8); }
            catch (Exception) { }
        }
    }

    protected override void OnStart(string[] args)
    {
        ProcessStartInfo info = new ProcessStartInfo(NodeExe, "\\"" + EntryScript + "\\"");
        info.UseShellExecute = false;
        info.CreateNoWindow = true;
        info.WorkingDirectory = WorkDir;
        info.RedirectStandardOutput = true;
        info.RedirectStandardError = true;
        child = new Process();
        child.StartInfo = info;
        child.EnableRaisingEvents = true;
        child.OutputDataReceived += (s, e) => Log(e.Data);
        child.ErrorDataReceived += (s, e) => Log(e.Data);
        child.Exited += (s, e) =>
        {
            if (stopping) return;
            Log("node exited with code " + child.ExitCode + "; the service ends so that its recovery options restart it");
            Environment.Exit(1);
        };
        child.Start();
        child.BeginOutputReadLine();
        child.BeginErrorReadLine();
        Log("started node, pid " + child.Id);
    }

    protected override void OnStop() { StopChild(); }

    protected override void OnShutdown() { StopChild(); }

    void StopChild()
    {
        stopping = true;
        try
        {
            if (child != null && !child.HasExited)
            {
                child.Kill();
                child.WaitForExit(10000);
            }
        }
        catch (Exception) { }
        Log("stopped");
    }

    public static void Main() { ServiceBase.Run(new ArasHouseBrokerService()); }
}
`;
}

function psHashtable(entries: Readonly<Partial<Record<string, string>>>): string {
  return `@{ ${Object.entries(entries)
    .map(([k, v]) => `${k} = ${psQuote(v as string)}`)
    .join("; ")} }`;
}

/**
 * The text of `setup-host.ps1`. Every path in it is derived from `root` by names.ts; it writes nothing
 * without `-Apply` and nothing outside the root (beyond the service, its group membership and an opt-in
 * Defender exclusion). Throws when an option is unusable.
 */
export function renderSetupHostScript(options: SetupScriptOptions): string {
  checkOptions(options);
  const root = assertValidRoot(options.root ?? DEFAULT_INSTALL_ROOT);
  const folders = ROOT_FOLDERS.map((name) => `    ${psQuote(name)} = ${psQuote(win32.join(root, name))}`).join("\n");
  const acl = ROOT_FOLDERS.map((name) => `    ${psQuote(name)} = ${psHashtable(FOLDER_ACL[name])}`).join("\n");
  const prerequisites = prerequisitesFor(options.flavors)
    .map((p) => `    [ordered]@{ id = ${psQuote(p.id)}; flavors = ${psQuote(p.flavors.join(", "))}; check = { ${PREREQUISITE_CHECKS[p.id]} } }`)
    .join("\n");
  const appFiles = options.appFiles.map((f) => `    @{ path = ${psQuote(f.path)}; sha256 = ${psQuote(f.sha256)} }`).join("\n");
  const iis = IIS_COMPONENTS.map(psQuote).join(", ");
  const wrapper = brokerWrapperSource(root);
  if (wrapper.split(/\r?\n/).some((l) => l.startsWith("'@"))) throw new Error("the wrapper source cannot sit in a here-string");

  return `# setup-host.ps1: the one-time host preparation for arashouse (ticket 21), generated by \`arashouse setup\` ${options.version}.
# Run it in an elevated Windows PowerShell 5.1. Without -Apply it prints what it would change (\`would do:\` lines) and changes
# nothing; with -Apply each change is printed (\`do:\`) and made. The last thing it prints is \`result:\` and the result as JSON.
#
#   setup-host.ps1                                    the plan (needs no elevation; some reads need it)
#   setup-host.ps1 -Apply                             create the folders, set their ACLs, install and start the broker service
#   setup-host.ps1 -Apply -DefenderExclusion          ... and exclude the install root from Defender scanning (off by default)
#   setup-host.ps1 -Apply -SlotIdleTimeoutMinutes 5   ... and record a short idle timeout for slot app pools (ticket 25 sets it)
#   setup-host.ps1 -Apply -UpdateBroker               install this bundle's broker build over the installed one and restart it
#   setup-host.ps1 -Uninstall [-RemoveRoot] -Apply    remove the service; with -RemoveRoot also the root, if it holds only arashouse folders
#
# Idempotent: a second run changes only what differs (a folder's ACL that drifted, a stopped service). It writes only under the
# install root, plus the service, its recovery options, its membership of Administrators and (opt-in) one Defender exclusion. It
# never installs a prerequisite: it lists what is missing. It reads no secret and writes none; the JSON holds names and SIDs only.
# Exit codes: 0 ok, 1 a step failed or the result is not ok, 2 refused arguments, 4 not elevated.
param(
    [switch]$Apply,
    [switch]$Uninstall,
    [switch]$RemoveRoot,
    [switch]$UpdateBroker,
    [switch]$DefenderExclusion,
    [ValidateRange(1, 1440)][int]$SlotIdleTimeoutMinutes
)
$ErrorActionPreference = 'Stop'

# ---- generated from src/core (names.ts, setup-host.ts, flavors.ts); do not edit ----
$ToolVersion = ${psQuote(options.version)}
$Root = ${psQuote(root)}
$Folders = [ordered]@{
${folders}
}
$FolderAcl = @{
${acl}
}
$ServiceName = ${psQuote(BROKER_SERVICE_NAME)}
$BrokerAccount = ${psQuote(serviceAccount())}
$BrokerSid = ${psQuote(serviceSid())}
$WorkerName = ${psQuote(options.worker.name)}
$WorkerSid = ${psQuote(options.worker.sid)}
$SqlServiceName = ${psQuote(SQL_SERVICE_NAME)}
$BrokerDir = ${psQuote(brokerDir(root))}
$AppDir = ${psQuote(brokerAppDir(root))}
$PackageJson = ${psQuote(win32.join(brokerDir(root), "package.json"))}
$EntryScript = ${psQuote(brokerEntryScript(root))}
$ClientScript = ${psQuote(brokerClientScript(root))}
$ServiceExe = ${psQuote(brokerServiceExe(root))}
$RecordFile = ${psQuote(setupRecordFile(root))}
$MinNodeMajor = ${MIN_NODE_MAJOR}
$IisComponents = @(${iis})
$Prerequisites = @(
${prerequisites}
)
$PackageJsonSha256 = ${psQuote(options.packageJsonSha256)}
$AppFiles = @(
${appFiles}
)
$WrapperSource = @'
${wrapper}'@
# ---- end of generated values ----

$SystemSid = 'S-1-5-18'
$AdministratorsSid = 'S-1-5-32-544'
$TrustedInstallerSid = 'S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464'
$Rights = @{
    full = [Security.AccessControl.FileSystemRights]::FullControl
    modify = [Security.AccessControl.FileSystemRights]::Modify
    read = [Security.AccessControl.FileSystemRights]::ReadAndExecute
}
# Rights on the root folder itself that would let a non-administrator rename it away and plant a new root (and so a new service binary).
$RootGuardedRights = [int]([Security.AccessControl.FileSystemRights]::Delete -bor [Security.AccessControl.FileSystemRights]::ChangePermissions -bor
    [Security.AccessControl.FileSystemRights]::TakeOwnership -bor [Security.AccessControl.FileSystemRights]::DeleteSubdirectoriesAndFiles)
$WholeTree = [Security.AccessControl.InheritanceFlags]'ContainerInherit, ObjectInherit'
$Changes = New-Object System.Collections.ArrayList
$Planned = New-Object System.Collections.ArrayList
$Errors = New-Object System.Collections.ArrayList

function Fail([int]$Code, [string]$Message) {
    [Console]::Error.WriteLine("error: $Message")
    exit $Code
}

# Every change goes through here: without -Apply it is only printed.
function Invoke-Change([string]$Text, [scriptblock]$Action) {
    if (-not $Apply) {
        Write-Host "would do: $Text"
        [void]$Planned.Add($Text)
        return
    }
    Write-Host "do: $Text"
    & $Action
    [void]$Changes.Add($Text)
}

function Invoke-Native([string]$File, [string[]]$Arguments, [int[]]$Ok = @(0)) {
    # In Windows PowerShell 5.1 a redirected stderr line is an error record, so not under 'Stop' here.
    $ErrorActionPreference = 'Continue'
    $out = & $File @Arguments 2>&1
    $code = $LASTEXITCODE
    if ($Ok -notcontains $code) { throw ('{0} {1} exited {2}: {3}' -f $File, ($Arguments -join ' '), $code, (($out | Out-String).Trim())) }
    return $out
}

function Invoke-Quiet([string]$File, [string[]]$Arguments, [string]$Stdin = '') {
    # A read-only native command: its stdout (stderr dropped) and exit code.
    $ErrorActionPreference = 'Continue'
    if ($Stdin -ne '') { $out = $Stdin | & $File @Arguments 2>$null } else { $out = & $File @Arguments 2>$null }
    return [ordered]@{ code = $LASTEXITCODE; out = (@($out | ForEach-Object { [string]$_ }) -join [Environment]::NewLine) }
}

function Test-Elevated {
    $principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
    return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

function Assert-UnderRoot([string]$Path) {
    $full = [IO.Path]::GetFullPath($Path)
    if (-not $full.StartsWith($Root + '\\', [StringComparison]::OrdinalIgnoreCase) -and $full -ine $Root) { throw "refused: $Path is not under $Root" }
    if ($full -match '(?i)program files') { throw "refused: $Path is under Program Files" }
}

function Test-ReparsePoint([string]$Path) {
    $item = Get-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue
    return ($null -ne $item) -and (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)
}

# ---- reads ----

function Test-Iis {
    $stp = Get-ItemProperty -LiteralPath 'HKLM:\\SOFTWARE\\Microsoft\\InetStp' -ErrorAction SilentlyContinue
    if (-not $stp -or [int]$stp.MajorVersion -lt 10) { return 'IIS 10 is not installed' }
    $components = Get-ItemProperty -LiteralPath 'HKLM:\\SOFTWARE\\Microsoft\\InetStp\\Components' -ErrorAction SilentlyContinue
    $missing = @($IisComponents | Where-Object { -not $components -or $components.$_ -ne 1 })
    if ($missing.Count -gt 0) { return ('IIS role services missing: {0}' -f ($missing -join ', ')) }
    return $null
}

function Test-NetFx([int]$Release) {
    $full = Get-ItemProperty -LiteralPath 'HKLM:\\SOFTWARE\\Microsoft\\NET Framework Setup\\NDP\\v4\\Full' -ErrorAction SilentlyContinue
    if (-not $full -or [int]$full.Release -lt $Release) { return '.NET Framework 4.7.2 or newer is not installed' }
    return $null
}

function Test-AspNetCore([string]$Version) {
    $dir = Join-Path $env:ProgramFiles 'dotnet\\shared\\Microsoft.AspNetCore.App'
    $found = @(Get-ChildItem -LiteralPath $dir -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name.StartsWith($Version + '.') })
    if ($found.Count -eq 0) { return "the ASP.NET Core $Version runtime (its Hosting Bundle) is not installed" }
    return $null
}

function Test-RegistryKey([string]$Key, [string]$What) {
    if (-not (Test-Path -LiteralPath $Key)) { return "$What is not installed" }
    return $null
}

function Test-VcRedist {
    $vc = Get-ItemProperty -LiteralPath 'HKLM:\\SOFTWARE\\Microsoft\\VisualStudio\\14.0\\VC\\Runtimes\\x64' -ErrorAction SilentlyContinue
    if (-not $vc -or [int]$vc.Installed -ne 1) { return 'the Visual C++ 2015-2022 x64 runtime is not installed' }
    return $null
}

function Get-MissingPrerequisites {
    $out = New-Object System.Collections.ArrayList
    foreach ($p in $Prerequisites) {
        $detail = & $p.check
        if ($detail) { [void]$out.Add([ordered]@{ id = $p.id; flavors = $p.flavors; detail = $detail }) }
    }
    return , @($out)
}

function Get-SidName([string]$Sid) {
    try { return (New-Object Security.Principal.SecurityIdentifier($Sid)).Translate([Security.Principal.NTAccount]).Value } catch { return $Sid }
}

function Get-SqlAccount {
    # The SQL Server service account, as its service definition names it; $null when there is no such service.
    $svc = Get-CimInstance Win32_Service -Filter ("Name='{0}'" -f $SqlServiceName) -ErrorAction SilentlyContinue
    if (-not $svc -or -not $svc.StartName) { return $null }
    $name = [string]$svc.StartName
    if ($name -ieq 'LocalSystem') { return [ordered]@{ name = $name; sid = $SystemSid } }
    $sid = (New-Object Security.Principal.NTAccount($name)).Translate([Security.Principal.SecurityIdentifier]).Value
    return [ordered]@{ name = $name; sid = $sid }
}

function Get-NodeExe {
    # The node.exe the service runs: the one on PATH, else the default install. It runs as a local administrator, so a
    # node.exe (or a folder holding it) that a non-administrator could change is refused.
    $cmd = Get-Command node.exe -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
    $path = if ($cmd) { $cmd.Source } else { Join-Path $env:ProgramFiles 'nodejs\\node.exe' }
    if (-not (Test-Path -LiteralPath $path)) { return [ordered]@{ path = $null; version = $null; problem = 'node.exe was not found (Node 20 or newer is needed on Windows)' } }
    $version = (Invoke-Quiet $path @('--version')).out.Trim()
    $problem = $null
    if ($version -notmatch '^v(\\d+)\\.' -or [int]$Matches[1] -lt $MinNodeMajor) { $problem = "node.exe is $version; Node $MinNodeMajor or newer is needed" }
    foreach ($target in @($path, (Split-Path -Parent $path))) {
        $writers = Get-NonAdminWriters $target
        if ($writers.Count -gt 0) { $problem = ('{0} can be changed by {1}; the broker would run it as an administrator' -f $target, ($writers -join ', ')) }
    }
    return [ordered]@{ path = $path; version = $version; problem = $problem }
}

function Get-NonAdminWriters([string]$Path) {
    $write = [int]([Security.AccessControl.FileSystemRights]::WriteData -bor [Security.AccessControl.FileSystemRights]::AppendData -bor
        [Security.AccessControl.FileSystemRights]::Delete -bor [Security.AccessControl.FileSystemRights]::ChangePermissions -bor
        [Security.AccessControl.FileSystemRights]::TakeOwnership)
    $trusted = @($SystemSid, $AdministratorsSid, $TrustedInstallerSid, 'S-1-3-0')
    $out = New-Object System.Collections.ArrayList
    $acl = (Get-Item -LiteralPath $Path -Force).GetAccessControl('Access')
    foreach ($r in $acl.GetAccessRules($true, $true, [Security.Principal.SecurityIdentifier])) {
        if ($r.AccessControlType -ne 'Allow' -or ($r.PropagationFlags -band [Security.AccessControl.PropagationFlags]::InheritOnly)) { continue }
        if ($trusted -contains $r.IdentityReference.Value) { continue }
        if (([int]$r.FileSystemRights -band $write) -ne 0) { [void]$out.Add((Get-SidName $r.IdentityReference.Value)) }
    }
    return , @($out | Select-Object -Unique)
}

function Get-Sids($SqlAccount) {
    $sids = @{ system = $SystemSid; administrators = $AdministratorsSid; broker = $BrokerSid; worker = $WorkerSid; sql = $null }
    if ($SqlAccount) { $sids.sql = $SqlAccount.sid }
    return $sids
}

function Get-FolderDeviations([string]$Path, $Plan, $Sids) {
    # How the folder's DACL differs from the plan; empty when it matches exactly.
    $out = New-Object System.Collections.ArrayList
    try { $acl = (Get-Item -LiteralPath $Path -Force).GetAccessControl('Access') } catch { [void]$out.Add('its ACL cannot be read here'); return , @($out) }
    if (-not $acl.AreAccessRulesProtected) { [void]$out.Add('it inherits from the root') }
    $have = @{}
    foreach ($r in $acl.GetAccessRules($true, $true, [Security.Principal.SecurityIdentifier])) {
        $sid = $r.IdentityReference.Value
        if ($r.AccessControlType -ne 'Allow') { [void]$out.Add(('{0} has a deny rule' -f (Get-SidName $sid))); continue }
        if ($r.InheritanceFlags -ne $WholeTree -or $r.PropagationFlags -ne 'None') { [void]$out.Add(('{0} has a rule that does not cover the whole folder' -f (Get-SidName $sid))) }
        $have[$sid] = [int]$have[$sid] -bor [int]$r.FileSystemRights
    }
    foreach ($principal in $Plan.Keys) {
        $sid = $Sids[$principal]
        if (-not $sid) { [void]$out.Add("$principal is not known on this host"); continue }
        # .NET adds Synchronize to every allow rule it writes; Modify and ReadAndExecute do not include it.
        $want = [int]$Rights[$Plan[$principal]] -bor [int][Security.AccessControl.FileSystemRights]::Synchronize
        if (([int]$have[$sid] -bor [int][Security.AccessControl.FileSystemRights]::Synchronize) -ne $want) { [void]$out.Add(('{0} should have {1}' -f (Get-SidName $sid), $Plan[$principal])) }
        $have.Remove($sid)
    }
    foreach ($sid in $have.Keys) { [void]$out.Add(('{0} should have no access' -f (Get-SidName $sid))) }
    return , @($out)
}

function Get-RootDeviations {
    $out = New-Object System.Collections.ArrayList
    try { $acl = (Get-Item -LiteralPath $Root -Force).GetAccessControl('Access') } catch { [void]$out.Add('its ACL cannot be read here'); return , @($out) }
    foreach ($r in $acl.GetAccessRules($true, $true, [Security.Principal.SecurityIdentifier])) {
        if ($r.AccessControlType -ne 'Allow' -or ($r.PropagationFlags -band [Security.AccessControl.PropagationFlags]::InheritOnly)) { continue }
        if (@($SystemSid, $AdministratorsSid, $TrustedInstallerSid) -contains $r.IdentityReference.Value) { continue }
        if (([int]$r.FileSystemRights -band $RootGuardedRights) -ne 0) { [void]$out.Add(('{0} may delete, rename or re-permission the root' -f (Get-SidName $r.IdentityReference.Value))) }
    }
    return , @($out)
}

function Get-DefenderExcluded {
    try {
        $paths = @((Get-MpPreference -ErrorAction Stop).ExclusionPath)
        if ($paths -match '^N/A') { return $null }
        return [bool]($paths | Where-Object { $_ -ieq $Root })
    } catch { return $null }
}

function Get-AdminsGroupName {
    return ((Get-SidName $AdministratorsSid) -split '\\\\')[-1]
}

function Test-BrokerIsAdmin {
    $r = Invoke-Quiet 'net.exe' @('localgroup', (Get-AdminsGroupName))
    if ($r.code -ne 0) { return $null }
    return [bool](($r.out -split '\r?\n') | Where-Object { $_.Trim() -ieq $BrokerAccount })
}

function Test-Recovery {
    $r = Invoke-Quiet 'sc.exe' @('qfailure', $ServiceName)
    return ($r.code -eq 0) -and ($r.out -match 'RESTART')
}

function Get-BrokerState {
    $svc = Get-Service -Name $ServiceName -ErrorAction SilentlyContinue
    $state = [ordered]@{ service = $ServiceName; installed = [bool]$svc; status = $null; account = $null; administrator = $null; recovery = $null; binary = $null; ping = 'not run' }
    if (-not $svc) { return $state }
    $cim = Get-CimInstance Win32_Service -Filter ("Name='{0}'" -f $ServiceName)
    $state.status = [string]$svc.Status
    $state.account = [string]$cim.StartName
    $state.binary = [string]$cim.PathName
    $state.administrator = Test-BrokerIsAdmin
    $state.recovery = Test-Recovery
    return $state
}

function Invoke-BrokerPing([string]$Node) {
    # The ping a worker's client makes: node.exe <client.js>, the request on stdin, the response on stdout.
    $last = 'no answer'
    for ($i = 0; $i -lt 10; $i++) {
        try {
            $r = Invoke-Quiet $Node @($ClientScript, '--timeout-ms', '5000') '{"id":"setup-host-ping","verb":"ping"}'
            $response = $r.out.Trim() | ConvertFrom-Json
            if ($response.ok -and $response.result.ok) { return 'ok' }
            $last = if ($response.error) { [string]$response.error.kind } else { 'not ok' }
        } catch { $last = $_.Exception.Message }
        Start-Sleep -Seconds 1
    }
    return "failed: $last"
}

function Read-PreviousIdleTimeout {
    try {
        $old = Get-Content -LiteralPath $RecordFile -Raw -ErrorAction Stop | ConvertFrom-Json
        if ($old.options.slotIdleTimeoutMinutes) { return [int]$old.options.slotIdleTimeoutMinutes }
    } catch { }
    return $null
}

function Get-HostState($SqlAccount) {
    $sids = Get-Sids $SqlAccount
    # Not $folders: PowerShell names are case-insensitive, so that would hide $Folders.
    $folderStates = New-Object System.Collections.ArrayList
    foreach ($name in $Folders.Keys) {
        $path = $Folders[$name]
        $exists = Test-Path -LiteralPath $path -PathType Container
        $deviations = if ($exists) { Get-FolderDeviations $path $FolderAcl[$name] $sids } else { @('it does not exist') }
        [void]$folderStates.Add([ordered]@{ name = $name; path = $path; exists = $exists; aclOk = ($deviations.Count -eq 0); deviations = @($deviations) })
    }
    $rootExists = Test-Path -LiteralPath $Root -PathType Container
    $rootDeviations = if ($rootExists) { Get-RootDeviations } else { @('it does not exist') }
    return [ordered]@{
        root = [ordered]@{ path = $Root; exists = $rootExists; aclOk = ($rootDeviations.Count -eq 0); deviations = @($rootDeviations) }
        folders = $folderStates
        broker = Get-BrokerState
    }
}

# ---- changes ----

function New-Folder([string]$Path) {
    Assert-UnderRoot $Path
    New-Item -ItemType Directory -Path $Path -Force | Out-Null
}

function Set-FolderAcl([string]$Path, $Plan, $Sids) {
    # Replaces the whole DACL in one write: protected (nothing inherited from the root), every rule over the whole folder.
    Assert-UnderRoot $Path
    $sec = New-Object Security.AccessControl.DirectorySecurity
    $sec.SetAccessRuleProtection($true, $false)
    foreach ($principal in $Plan.Keys) {
        $sid = New-Object Security.Principal.SecurityIdentifier($Sids[$principal])
        $sec.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($sid, $Rights[$Plan[$principal]], $WholeTree, 'None', 'Allow')))
    }
    (Get-Item -LiteralPath $Path -Force).SetAccessControl($sec)
}

function Protect-Root {
    # Takes away the rights on the root folder itself that let a non-administrator rename or re-permission it. What the
    # root passes down to its other children (folders that are not arashouse's) stays exactly as it was.
    $item = Get-Item -LiteralPath $Root -Force
    $acl = $item.GetAccessControl('Access')
    if (-not $acl.AreAccessRulesProtected) {
        $acl.SetAccessRuleProtection($true, $true)
        $item.SetAccessControl($acl)
        $acl = $item.GetAccessControl('Access')
    }
    foreach ($r in @($acl.GetAccessRules($true, $false, [Security.Principal.SecurityIdentifier]))) {
        if ($r.AccessControlType -ne 'Allow' -or ($r.PropagationFlags -band [Security.AccessControl.PropagationFlags]::InheritOnly)) { continue }
        if (@($SystemSid, $AdministratorsSid, $TrustedInstallerSid) -contains $r.IdentityReference.Value) { continue }
        if (([int]$r.FileSystemRights -band $RootGuardedRights) -eq 0) { continue }
        $acl.RemoveAccessRuleSpecific($r)
        if ($r.InheritanceFlags -ne 'None') {
            $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($r.IdentityReference, $r.FileSystemRights, $r.InheritanceFlags, 'InheritOnly', 'Allow')))
        }
        $left = [int]$r.FileSystemRights -band (-bnot $RootGuardedRights)
        if ($left -ne 0) {
            $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($r.IdentityReference, [Security.AccessControl.FileSystemRights]$left, 'None', 'None', 'Allow')))
        }
    }
    $item.SetAccessControl($acl)
}

function Copy-BrokerApp {
    # Copies the build next to this script and checks every file against the SHA-256 this script was generated with.
    Assert-UnderRoot $AppDir
    $source = Join-Path $PSScriptRoot 'app'
    Invoke-Native 'robocopy.exe' @($source, $AppDir, '/MIR', '/NFL', '/NDL', '/NJH', '/NJS', '/NP', '/R:1', '/W:1') @(0, 1, 2, 3) | Out-Null
    Copy-Item -LiteralPath (Join-Path $PSScriptRoot 'package.json') -Destination $PackageJson -Force
    $bad = New-Object System.Collections.ArrayList
    foreach ($f in $AppFiles) {
        $p = Join-Path $AppDir $f.path
        if (-not (Test-Path -LiteralPath $p -PathType Leaf) -or (Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant() -ne $f.sha256) { [void]$bad.Add($f.path) }
    }
    if ((Get-FileHash -LiteralPath $PackageJson -Algorithm SHA256).Hash.ToLowerInvariant() -ne $PackageJsonSha256) { [void]$bad.Add('package.json') }
    $count = @(Get-ChildItem -LiteralPath $AppDir -Recurse -File -Force).Count
    if ($count -ne $AppFiles.Count) { [void]$bad.Add(('{0} files where {1} were expected' -f $count, $AppFiles.Count)) }
    if ($bad.Count -gt 0) { throw ('the copied broker build is not the one this script was generated with ({0}); the service was not started' -f (($bad | Select-Object -First 5) -join ', ')) }
}

function Build-Wrapper([string]$Node) {
    Assert-UnderRoot $ServiceExe
    if (Test-Path -LiteralPath $ServiceExe) { Remove-Item -LiteralPath $ServiceExe -Force }
    $source = $WrapperSource.Replace('@@NODE@@', $Node.Replace('"', '""'))
    Add-Type -TypeDefinition $source -Language CSharp -OutputAssembly $ServiceExe -OutputType ConsoleApplication -ReferencedAssemblies 'System.ServiceProcess'
}

function Stop-Broker {
    Stop-Service -Name $ServiceName -Force
    (Get-Service -Name $ServiceName).WaitForStatus('Stopped', [TimeSpan]::FromSeconds(30))
}

# ---- main ----

if ($RemoveRoot -and -not $Uninstall) { Fail 2 '-RemoveRoot goes with -Uninstall' }
if ($Uninstall -and ($UpdateBroker -or $DefenderExclusion -or $PSBoundParameters.ContainsKey('SlotIdleTimeoutMinutes'))) {
    Fail 2 '-Uninstall takes only -RemoveRoot and -Apply'
}
if ($Apply -and -not (Test-Elevated)) { Fail 4 '-Apply needs an elevated PowerShell (Run as administrator)' }
foreach ($p in @($Root) + @($Folders.Values) + @($AppDir, $EntryScript, $ServiceExe, $RecordFile)) { Assert-UnderRoot $p }
if (-not $Apply) { Write-Host 'dry run: nothing is changed; add -Apply (elevated) to make these changes' }

$mode = if ($Uninstall) { 'uninstall' } else { 'install' }
$node = $null
$sqlAccount = $null
$missing = @()
$idle = $null
$defender = $null
try {
    if (Test-ReparsePoint $Root) { throw "refused: $Root is a junction or symbolic link" }
    foreach ($path in $Folders.Values) { if (Test-ReparsePoint $path) { throw "refused: $path is a junction or symbolic link" } }

    if ($Uninstall) {
        $svc = Get-Service -Name $ServiceName -ErrorAction SilentlyContinue
        if ($svc) {
            if ($svc.Status -ne 'Stopped') { Invoke-Change "stop the service $ServiceName" { Stop-Broker } }
            if (Test-BrokerIsAdmin) { Invoke-Change "remove $BrokerAccount from the local Administrators group" { Invoke-Native 'net.exe' @('localgroup', (Get-AdminsGroupName), $BrokerAccount, '/delete') | Out-Null } }
            Invoke-Change "delete the service $ServiceName" { Invoke-Native 'sc.exe' @('delete', $ServiceName) | Out-Null }
        } else { Write-Host "skip: the service $ServiceName is not installed" }
        if ((Get-DefenderExcluded) -eq $true) { Invoke-Change "remove the Defender exclusion for $Root" { Remove-MpPreference -ExclusionPath $Root } }
        if ($RemoveRoot -and (Test-Path -LiteralPath $Root)) {
            $foreign = @(Get-ChildItem -LiteralPath $Root -Force | Where-Object { -not $Folders.Contains($_.Name) } | ForEach-Object { $_.Name })
            if ($foreign.Count -gt 0) { throw ('refused to remove {0}: it also holds {1}, which are not arashouse folders' -f $Root, ($foreign -join ', ')) }
            $links = @(Get-ChildItem -LiteralPath $Root -Recurse -Force -Attributes ReparsePoint -ErrorAction SilentlyContinue)
            if ($links.Count -gt 0) { throw ('refused to remove {0}: it holds a junction or link ({1})' -f $Root, $links[0].FullName) }
            Invoke-Change "remove $Root and everything in it" { Assert-UnderRoot $Root; Remove-Item -LiteralPath $Root -Recurse -Force }
        }
    } else {
        $node = Get-NodeExe
        if ($node.problem) { throw $node.problem }
        $sqlAccount = Get-SqlAccount
        if (-not $sqlAccount) { [void]$Errors.Add("the SQL Server service $SqlServiceName was not found: its account gets no access to golden, staging or sqldata") }
        $missing = Get-MissingPrerequisites
        foreach ($m in $missing) { Write-Host ('missing: {0} (for {1}): {2}' -f $m.id, $m.flavors, $m.detail) }
        $sids = Get-Sids $sqlAccount

        if (-not (Test-Path -LiteralPath $Root)) { Invoke-Change "create $Root" { New-Folder $Root } }
        # A function that returns an array with a leading comma is one object to @(), so count through a variable.
        $rootDeviations = if (Test-Path -LiteralPath $Root) { Get-RootDeviations } else { @('new') }
        if ($rootDeviations.Count -gt 0) {
            Invoke-Change "take delete, rename and re-permission rights on $Root itself from everyone but SYSTEM and Administrators (what it passes to its other folders is unchanged)" { Protect-Root }
        }
        foreach ($name in $Folders.Keys) {
            $path = $Folders[$name]
            if (-not (Test-Path -LiteralPath $path)) { Invoke-Change "create $path" { New-Folder $path } }
            $plan = $FolderAcl[$name]
            $deviations = if (Test-Path -LiteralPath $path) { Get-FolderDeviations $path $plan $sids } else { @('new') }
            if ($deviations.Count -gt 0) {
                $who = ($plan.Keys | Sort-Object | ForEach-Object { '{0} {1}' -f $(if ($_ -eq 'sql' -and $sqlAccount) { $sqlAccount.name } elseif ($_ -eq 'worker') { $WorkerName } elseif ($_ -eq 'broker') { $BrokerAccount } else { $_ }), $plan[$_] }) -join ', '
                $grants = @{}
                foreach ($k in $plan.Keys) { if ($sids[$k]) { $grants[$k] = $plan[$k] } }
                Invoke-Change ("set the ACL of {0}: {1}, nothing inherited" -f $path, $who) { Set-FolderAcl $path $grants $sids }
            }
        }

        $svc = Get-Service -Name $ServiceName -ErrorAction SilentlyContinue
        $restart = $UpdateBroker -and $svc -and $svc.Status -eq 'Running'
        if ($UpdateBroker -or -not (Test-Path -LiteralPath $EntryScript)) {
            if ($svc -and $svc.Status -ne 'Stopped') { Invoke-Change "stop the service $ServiceName to replace its build" { Stop-Broker } }
            Invoke-Change ("install the broker build (arashouse {0}, {1} files, each checked by SHA-256) in {2}" -f $ToolVersion, $AppFiles.Count, $AppDir) { Copy-BrokerApp }
        }
        if ($UpdateBroker -or -not (Test-Path -LiteralPath $ServiceExe)) {
            if ($svc -and $svc.Status -ne 'Stopped' -and -not $UpdateBroker) { Invoke-Change "stop the service $ServiceName to replace its wrapper" { Stop-Broker } }
            Invoke-Change ("compile the service wrapper {0}, which runs {1} {2}" -f $ServiceExe, $node.path, $EntryScript) { Build-Wrapper $node.path }
        }
        if (-not $svc) {
            Invoke-Change "create the service $ServiceName (automatic start) running as $BrokerAccount" {
                New-Service -Name $ServiceName -BinaryPathName ('"{0}"' -f $ServiceExe) -DisplayName 'arashouse broker' -Description 'The arashouse broker: leases disposable Aras instances (docs/broker.md).' -StartupType Automatic | Out-Null
                Invoke-Native 'sc.exe' @('sidtype', $ServiceName, 'unrestricted') | Out-Null
                Invoke-Native 'sc.exe' @('config', $ServiceName, 'obj=', $BrokerAccount) | Out-Null
            }
        } else {
            $current = (Get-CimInstance Win32_Service -Filter ("Name='{0}'" -f $ServiceName)).StartName
            if ($current -ine $BrokerAccount) { Invoke-Change "run the service $ServiceName as $BrokerAccount (it runs as $current)" { Invoke-Native 'sc.exe' @('config', $ServiceName, 'obj=', $BrokerAccount) | Out-Null } }
        }
        if (-not $svc -or -not (Test-Recovery)) {
            Invoke-Change "set the recovery of $ServiceName to restart after 5 s, 10 s, then 60 s" {
                Invoke-Native 'sc.exe' @('failure', $ServiceName, 'reset=', '86400', 'actions=', 'restart/5000/restart/10000/restart/60000') | Out-Null
                Invoke-Native 'sc.exe' @('failureflag', $ServiceName, '1') | Out-Null
            }
        }
        if (-not $svc -or -not (Test-BrokerIsAdmin)) {
            Invoke-Change "add $BrokerAccount to the local Administrators group (it creates IIS applications, pools and services)" { Invoke-Native 'net.exe' @('localgroup', (Get-AdminsGroupName), $BrokerAccount, '/add') | Out-Null }
        }
        if ($DefenderExclusion) {
            $defender = Get-DefenderExcluded
            if ($defender -ne $true) { Invoke-Change "add a Defender exclusion for $Root" { Add-MpPreference -ExclusionPath $Root } }
        }
        $idle = Read-PreviousIdleTimeout
        if ($PSBoundParameters.ContainsKey('SlotIdleTimeoutMinutes') -and $idle -ne $SlotIdleTimeoutMinutes) {
            Invoke-Change "record an idle timeout of $SlotIdleTimeoutMinutes minutes for slot app pools (ticket 25 sets it when it creates them)" { }
            if ($Apply) { $idle = $SlotIdleTimeoutMinutes }
        }
        $now = Get-Service -Name $ServiceName -ErrorAction SilentlyContinue
        if (-not $now -or $now.Status -ne 'Running' -or (-not $Apply -and $restart)) {
            Invoke-Change "start the service $ServiceName" {
                Start-Service -Name $ServiceName
                (Get-Service -Name $ServiceName).WaitForStatus('Running', [TimeSpan]::FromSeconds(30))
            }
        }
    }
} catch {
    [void]$Errors.Add($_.Exception.Message)
    [Console]::Error.WriteLine("error: $($_.Exception.Message)")
}

$state = if ($Uninstall -and $RemoveRoot -and $Apply -and -not (Test-Path -LiteralPath $Root)) { $null } else { Get-HostState $sqlAccount }
if ($state -and $node -and $node.path -and $state.broker.status -eq 'Running') { $state.broker.ping = Invoke-BrokerPing $node.path }
$installedOk = $state -and $state.root.exists -and $state.root.aclOk -and @($state.folders | Where-Object { -not $_.aclOk }).Count -eq 0 -and
    $state.broker.status -eq 'Running' -and $state.broker.account -ieq $BrokerAccount -and $state.broker.administrator -eq $true -and
    $state.broker.recovery -eq $true -and $state.broker.ping -eq 'ok'
$ok = ($Errors.Count -eq 0) -and $(if ($Uninstall) { -not $state -or -not $state.broker.installed } else { [bool]$installedOk })
if ($DefenderExclusion -or $Uninstall) { $defender = Get-DefenderExcluded }

$record = [ordered]@{
    schema = 1
    tool = 'setup-host.ps1'
    version = $ToolVersion
    time = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
    mode = $mode
    applied = [bool]$Apply
    elevated = [bool](Test-Elevated)
    ok = [bool]$ok
    root = $(if ($state) { $state.root } else { [ordered]@{ path = $Root; exists = $false; aclOk = $false; deviations = @('removed') } })
    folders = $(if ($state) { @($state.folders) } else { @() })
    principals = [ordered]@{
        broker = $BrokerAccount; brokerSid = $BrokerSid; worker = $WorkerName; workerSid = $WorkerSid
        sql = $(if ($sqlAccount) { $sqlAccount.name } else { $null }); sqlSid = $(if ($sqlAccount) { $sqlAccount.sid } else { $null })
    }
    broker = $(if ($state) { $state.broker } else { $null })
    node = $(if ($node) { [ordered]@{ path = $node.path; version = $node.version } } else { $null })
    prerequisites = [ordered]@{ checked = @($Prerequisites | ForEach-Object { $_.id }); missing = @($missing) }
    options = [ordered]@{ defenderExclusion = $defender; slotIdleTimeoutMinutes = $idle }
    changes = @($Changes)
    planned = @($Planned)
    errors = @($Errors)
}
$json = $record | ConvertTo-Json -Depth 6
if ($Apply -and (Test-Path -LiteralPath $BrokerDir)) { [IO.File]::WriteAllText($RecordFile, $json, (New-Object Text.ASCIIEncoding)) }
Write-Host 'result:'
Write-Host $json
if ($Apply -and -not $ok) { exit 1 }
if ($Errors.Count -gt 0) { exit 1 }
exit 0
`;
}

// ---- reading the record back (`arashouse doctor`) ---------------------------------------------

/** What the worker may do in each folder, as it can be seen from WSL (`modify` reads as `read`). */
export function workerAccess(folder: RootFolder): "read" | "none" {
  return FOLDER_ACL[folder].worker === undefined ? "none" : "read";
}

/** What `arashouse doctor` observes of the setup from WSL. */
export interface SetupObservation {
  /** The parsed `setup-host.json`; null when there is none; an Error when it cannot be read or parsed. */
  readonly record: unknown;
  /** Whether the root exists, as seen from WSL. */
  readonly rootExists: boolean;
  /** For each folder: whether the worker could list it, was denied, or found it missing. */
  readonly access: Readonly<Partial<Record<RootFolder, "read" | "denied" | "missing">>>;
}

export interface SetupFinding {
  readonly level: "ok" | "warn" | "fail";
  readonly check: string;
  readonly message: string;
}

interface RecordShape {
  ok?: unknown;
  time?: unknown;
  version?: unknown;
  applied?: unknown;
  mode?: unknown;
  errors?: unknown;
  root?: { exists?: unknown; aclOk?: unknown };
  folders?: unknown;
  broker?: { status?: unknown; ping?: unknown };
  prerequisites?: { missing?: unknown };
}

const asStrings = (v: unknown): string[] => (Array.isArray(v) ? v.filter((x): x is string => typeof x === "string") : []);

/** The doctor's findings for the setup: the record `setup-host.ps1` left, and the worker's own access to each folder. */
export function checkSetup(observation: SetupObservation): SetupFinding[] {
  const findings: SetupFinding[] = [];
  const hint = "run `arashouse setup` and the script it writes, elevated (docs/setup.md)";
  if (!observation.rootExists) return [{ level: "fail", check: "setup", message: `the install root is missing; ${hint}` }];
  const record = observation.record;
  if (record === null || record === undefined) {
    findings.push({ level: "fail", check: "setup", message: `no setup record (broker\\setup-host.json); ${hint}` });
  } else if (record instanceof Error || typeof record !== "object") {
    findings.push({ level: "fail", check: "setup", message: `the setup record cannot be read: ${record instanceof Error ? record.message : "not an object"}` });
  } else {
    const r = record as RecordShape;
    const when = `${typeof r.time === "string" ? r.time : "?"}, arashouse ${typeof r.version === "string" ? r.version : "?"}`;
    const folders = Array.isArray(r.folders) ? (r.folders as { name?: unknown; aclOk?: unknown }[]) : [];
    const badFolders = folders.filter((f) => f.aclOk !== true).map((f) => String(f.name));
    if (r.mode !== "install" || r.applied !== true) {
      findings.push({ level: "fail", check: "setup", message: `the last run (${when}) was not an applied install; ${hint}` });
    } else if (r.ok === true) {
      findings.push({ level: "ok", check: "setup", message: `applied ${when}: root present, ${folders.length} folders with their ACLs, broker ${String(r.broker?.status)} and answering` });
    } else {
      const why = [
        r.root?.exists !== true ? "the root is missing" : r.root?.aclOk !== true ? "the root's ACL" : "",
        badFolders.length > 0 ? `the ACL of ${badFolders.join(", ")}` : "",
        r.broker?.ping !== "ok" ? `the broker (${String(r.broker?.status)}, ping ${String(r.broker?.ping)})` : "",
        ...asStrings(r.errors),
      ].filter(Boolean);
      findings.push({ level: "fail", check: "setup", message: `the last run (${when}) did not finish: ${why.join("; ") || "see broker\\setup-host.json"}` });
    }
    const missing = Array.isArray(r.prerequisites?.missing) ? (r.prerequisites.missing as { id?: unknown; flavors?: unknown }[]) : [];
    if (missing.length > 0) {
      findings.push({ level: "warn", check: "prerequisites", message: `missing: ${missing.map((m) => `${String(m.id)} (for ${String(m.flavors)})`).join(", ")}` });
    } else if (r.applied === true) {
      findings.push({ level: "ok", check: "prerequisites", message: "every prerequisite of the flavors in media/ is installed" });
    }
  }

  const wrong: string[] = [];
  for (const folder of ROOT_FOLDERS) {
    const seen = observation.access[folder] ?? "missing";
    if (seen === "missing") wrong.push(`${folder}\\ is missing`);
    else if (workerAccess(folder) === "read" && seen !== "read") wrong.push(`the worker cannot read ${folder}\\`);
    else if (workerAccess(folder) === "none" && seen !== "denied") wrong.push(`the worker can read ${folder}\\`);
  }
  if (wrong.length > 0) findings.push({ level: "fail", check: "setup acl", message: wrong.join("; ") });
  else {
    const open = ROOT_FOLDERS.filter((f) => workerAccess(f) === "read");
    findings.push({ level: "ok", check: "setup acl", message: `the worker reads ${open.map((f) => `${f}\\`).join(", ")} and is kept out of the rest` });
  }
  return findings;
}
